language arduino
// P1AM-100: Tank pump control with low/high float switches.
// Slot 1: Discrete Input Module
//   Channel 1: Low Float Switch (NO) - Turns ON when water is low.
//   Channel 2: High Float Switch (NO) - Turns ON when water is high.
// Slot 2: Discrete Output Module
//   Channel 1: Pump Contactor (ON to run pump).
// Logic: Start pump when Low Float is ON. Stop pump when High Float is ON.
// The pump stays running (seal-in) until the High Float switch opens the circuit.

#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
const int lowFloatPin = 1;
const int highFloatPin = 2;
const int pumpPin = 1;

bool pumpRunning = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs: NO switch is ON (true) when water level triggers it.
  bool lowFloat = P1.readDiscrete(inSlot, lowFloatPin);
  bool highFloat = P1.readDiscrete(inSlot, highFloatPin);

  // Logic:
  // Start pump if low float is ON.
  // Stop pump if high float is ON.
  // Otherwise, keep the pump in its current state (seal-in).
  if (lowFloat) {
    pumpRunning = true;
  } else if (highFloat) {
    pumpRunning = false;
  }
  // If neither is active, pumpRunning retains its previous value.

  // Write output: Turn pump contactor ON or OFF.
  P1.writeDiscrete(pumpRunning, outSlot, pumpPin);
}
END

