MAKE CODE: Button held LED
language arduino
// A push button on pin 2 (connected to GND) lights the LED on pin 13
// while the button is held down. Uses the internal pull-up resistor.
// Wiring: Button between pin 2 and GND. LED anode to pin 13, cathode to GND.

const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Enable internal pull-up resistor
  pinMode(ledPin, OUTPUT);          // Set LED pin as output
}

void loop() {
  // Read the button state. Since it's pull-up, it reads HIGH when not pressed,
  // and LOW when pressed (connected to ground).
  int buttonState = digitalRead(buttonPin);

  // If the button is pressed (LOW), turn the LED on.
  // Otherwise, turn it off.
  if (buttonState == LOW) {
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
}
END

Here is the Arduino sketch to sweep a servo on pin 9:

MAKE CODE: Servo Sweep
language arduino
// Sweep a hobby servo from 0 to 180 degrees and back.
// Wiring: servo signal (orange/white) to pin 9, red to 5V, brown/black to GND.
// A big servo needs its own 5-6 V supply (grounds joined), not the Uno's 5V.
#include <Servo.h>

Servo arm;
const int servoPin = 9;

void setup() {
  arm.attach(servoPin);
}

void loop() {
  for (int angle = 0; angle <= 180; angle += 2) {
    arm.write(angle);
    delay(15);
  }
  for (int angle = 180; angle >= 0; angle -= 2) {
    arm.write(angle);
    delay(15);
  }
}
END

MAKE CODE: Sales CSV Max Amount
language python
# Reads sales.csv and prints the largest value in the 'amount' column.
# Usage: python3 sales_max.py sales.csv
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 sales_max.py sales.csv")
        return

    filename = sys.argv[1]
    max_amount = None

    try:
        with open(filename, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                # Ensure the 'amount' column exists and is numeric
                if 'amount' in row:
                    try:
                        val = float(row['amount'])
                        if max_amount is None or val > max_amount:
                            max_amount = val
                    except ValueError:
                        # Skip rows where amount is not a valid number
                        continue

        if max_amount is not None:
            print(f"{max_amount}")
        else:
            print("No valid numeric amounts found.")

    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
    except Exception as e:
        print(f"Error reading file: {e}")

if __name__ == "__main__":
    main()
END

